-- =====================================================================
--  SQL Quest -- sample database  (generated by tools/generate_seed.py)
--
--  A small online music-gear store: catalogue, customers, staff, orders,
--  payments, reviews and web traffic. Everything a SQL learner needs:
--  foreign keys, NULLs, a self-referencing employee hierarchy, a nested
--  category tree, dates, money and a JSON column.
-- =====================================================================

PRAGMA foreign_keys = ON;

CREATE TABLE categories (
  category_id   INTEGER PRIMARY KEY,
  name          TEXT    NOT NULL,
  parent_id     INTEGER REFERENCES categories(category_id)
);

CREATE TABLE suppliers (
  supplier_id   INTEGER PRIMARY KEY,
  name          TEXT    NOT NULL,
  country       TEXT    NOT NULL,
  city          TEXT,
  lead_time_days INTEGER NOT NULL,
  rating        REAL
);

CREATE TABLE products (
  product_id    INTEGER PRIMARY KEY,
  name          TEXT    NOT NULL,
  category_id   INTEGER NOT NULL REFERENCES categories(category_id),
  supplier_id   INTEGER REFERENCES suppliers(supplier_id),
  unit_price    REAL    NOT NULL CHECK (unit_price >= 0),
  units_in_stock INTEGER NOT NULL DEFAULT 0,
  reorder_level INTEGER,
  discontinued  INTEGER NOT NULL DEFAULT 0 CHECK (discontinued IN (0, 1)),
  released_on   TEXT
);

CREATE TABLE product_meta (
  product_id    INTEGER PRIMARY KEY REFERENCES products(product_id),
  attributes    TEXT NOT NULL          -- JSON document
);

CREATE TABLE customers (
  customer_id   INTEGER PRIMARY KEY,
  first_name    TEXT    NOT NULL,
  last_name     TEXT    NOT NULL,
  email         TEXT    NOT NULL UNIQUE,
  country       TEXT,
  city          TEXT,
  signup_date   TEXT    NOT NULL,
  birth_date    TEXT,
  loyalty_tier  TEXT    NOT NULL DEFAULT 'bronze',
  referred_by   INTEGER REFERENCES customers(customer_id)
);

CREATE TABLE employees (
  employee_id   INTEGER PRIMARY KEY,
  first_name    TEXT    NOT NULL,
  last_name     TEXT    NOT NULL,
  title         TEXT    NOT NULL,
  department    TEXT    NOT NULL,
  manager_id    INTEGER REFERENCES employees(employee_id),
  hire_date     TEXT    NOT NULL,
  salary        REAL    NOT NULL,
  region        TEXT
);

CREATE TABLE orders (
  order_id      INTEGER PRIMARY KEY,
  customer_id   INTEGER NOT NULL REFERENCES customers(customer_id),
  employee_id   INTEGER REFERENCES employees(employee_id),
  order_date    TEXT    NOT NULL,
  ship_date     TEXT,
  status        TEXT    NOT NULL,
  shipping_cost REAL    NOT NULL DEFAULT 0,
  ship_country  TEXT
);

CREATE TABLE order_items (
  order_id      INTEGER NOT NULL REFERENCES orders(order_id),
  item_no       INTEGER NOT NULL,
  product_id    INTEGER NOT NULL REFERENCES products(product_id),
  quantity      INTEGER NOT NULL CHECK (quantity > 0),
  unit_price    REAL    NOT NULL,
  discount      REAL    NOT NULL DEFAULT 0,
  PRIMARY KEY (order_id, item_no)
);

CREATE TABLE payments (
  payment_id    INTEGER PRIMARY KEY,
  order_id      INTEGER NOT NULL REFERENCES orders(order_id),
  method        TEXT    NOT NULL,
  amount        REAL    NOT NULL,
  paid_at       TEXT    NOT NULL
);

CREATE TABLE reviews (
  review_id     INTEGER PRIMARY KEY,
  product_id    INTEGER NOT NULL REFERENCES products(product_id),
  customer_id   INTEGER NOT NULL REFERENCES customers(customer_id),
  rating        INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment       TEXT,
  created_at    TEXT    NOT NULL
);

CREATE TABLE web_sessions (
  session_id    INTEGER PRIMARY KEY,
  customer_id   INTEGER REFERENCES customers(customer_id),
  started_at    TEXT    NOT NULL,
  duration_sec  INTEGER NOT NULL,
  device        TEXT    NOT NULL,
  landing_page  TEXT    NOT NULL
);

CREATE INDEX idx_orders_customer ON orders(customer_id);
CREATE INDEX idx_order_items_product ON order_items(product_id);















































































